AxMacroDictionary.Source:
/* %1 InventDimId           */
/* %2 InventDim             */
/* %3 InventDimCheck        */
/* %4 InventTable           */

join %2
where (%2.InventDimId     == %1)
&&    (%2.configId        == %3.configId       || !%4.configActive())
&&    (%2.InventColorId   == %3.InventColorId  || !%4.colorActive())
&&    (%2.InventSizeId    == %3.InventSizeId   || !%4.sizeActive())

#InventDimDevelop
